<div class="top"><div><a href="/admin/clients">← Clients</a><h1><?= e($u['name'] ?: $u['email']) ?></h1></div><form method="post" action="/admin/clients/<?= (int) $u['id'] ?>/actif"><?= csrf_field() ?><button class="btn <?= $u['active'] ? 'btn-d' : 'btn-p' ?> btn-sm"><?= $u['active'] ? 'Désactiver le compte' : 'Réactiver le compte' ?></button></form><?php if (can('settings') && !$orders): ?><form method="post" action="/admin/clients/<?= (int) $u['id'] ?>/supprimer" data-confirm="Supprimer ce compte client ?"><?= csrf_field() ?><button class="btn btn-d btn-sm">Supprimer</button></form><?php endif; ?></div>
<div class="grid g2"><div class="card"><h2>Informations</h2><p><?= e($u['email']) ?><br><?= e($u['phone']) ?><br><?= e($u['company']) ?><br>Inscrit le <?= fdate($u['created_at']) ?> · dernière connexion <?= fdate($u['last_login'], true) ?></p><?php foreach ($addr as $a): ?><p class="muted" style="font-size:14px"><?= e($a['label']) ?> : <?= e($a['address']) ?>, <?= e($a['commune']) ?></p><?php endforeach; ?></div>
<div class="card"><h2>Devis</h2><?php foreach ($quotes as $q): ?><p><a href="/admin/devis/<?= (int) $q['id'] ?>"><?= e($q['ref']) ?></a> <?= status_badge(QUOTE_STATUS, $q['status']) ?></p><?php endforeach; ?><?php if (!$quotes): ?><p class="muted">Aucun devis.</p><?php endif; ?></div></div>
<div class="card"><h2>Commandes</h2><table class="tbl"><tbody><?php foreach ($orders as $o): ?><tr><td><a href="/admin/commandes/<?= (int) $o['id'] ?>"><b><?= e($o['ref']) ?></b></a></td><td><?= fdate($o['created_at']) ?></td><td><?= status_badge(order_status_all(), $o['status']) ?></td><td class="right"><?= money($o['total']) ?></td></tr><?php endforeach; ?><?php if (!$orders): ?><tr><td class="muted">Aucune commande.</td></tr><?php endif; ?></tbody></table></div>
